values
  ('coding', 'Loops', 1, 'What does this code print?', array['75', '76', '55', '21'], 1, 'The loop runs for i = 3 to 7 (7 included), adding i × 3 to s each time. Pass by pass, s is 10 → 22 → 37 → 55 → 76. So it prints 76.', 40, 'coding-loop-sum', 'c48234d5294d9cd7', '{"c":"int s = 1;\nfor (int i = 3; i <= 7; i++) {\n  s += i * 3;\n}\nprintf(\"%d \", s);","cpp":"int s = 1;\nfor (int i = 3; i <= 7; i++) {\n  s += i * 3;\n}\ncout << s << \" \";","java":"int s = 1;\nfor (int i = 3; i <= 7; i++) {\n  s += i * 3;\n}\nSystem.out.print(s + \" \");","python":"s = 1\nfor i in range(3, 8):\n    s += i * 3\nprint(s, end=\" \")","pseudo":"Integer s = 1\nfor i = 3 to 7\n  s = s + i * 3\nend for\nprint s"}'::jsonb),
