  ('coding', 'Nested Loops', 2, 'What does this code print?', array['7', '3', '6', '9'], 2, 'The inner loop runs 3 − i + 1 times for each i from 1 to 3. Pass by pass, c is 3 → 5 → 6. Total: 6.', 50, 'coding-nested-count', '72d61f16a332d7bd', '{"c":"int c = 0;\nfor (int i = 1; i <= 3; i++) {\n  for (int j = i; j <= 3; j++) {\n    c += 1;\n  }\n}\nprintf(\"%d \", c);","cpp":"int c = 0;\nfor (int i = 1; i <= 3; i++) {\n  for (int j = i; j <= 3; j++) {\n    c += 1;\n  }\n}\ncout << c << \" \";","java":"int c = 0;\nfor (int i = 1; i <= 3; i++) {\n  for (int j = i; j <= 3; j++) {\n    c += 1;\n  }\n}\nSystem.out.print(c + \" \");","python":"c = 0\nfor i in range(1, 4):\n    for j in range(i, 4):\n        c += 1\nprint(c, end=\" \")","pseudo":"Integer c = 0\nfor i = 1 to 3\n  for j = i to 3\n    c = c + 1\n  end for\nend for\nprint c"}'::jsonb),
