  ('coding', 'While Loops', 2, 'What does this code print?', array['17', '18', '1', '13'], 0, 'x % 10 is the last digit and x / 10 drops it, so the loop adds up the digits of 1934: 1 + 9 + 3 + 4 = 17.', 50, 'coding-digit-sum', 'b7b17e9fd2d9616a', '{"c":"int x = 1934;\nint s = 0;\nwhile (x > 0) {\n  s += x % 10;\n  x /= 10;\n}\nprintf(\"%d \", s);","cpp":"int x = 1934;\nint s = 0;\nwhile (x > 0) {\n  s += x % 10;\n  x /= 10;\n}\ncout << s << \" \";","java":"int x = 1934;\nint s = 0;\nwhile (x > 0) {\n  s += x % 10;\n  x /= 10;\n}\nSystem.out.print(s + \" \");","python":"x = 1934\ns = 0\nwhile x > 0:\n    s += x % 10\n    x //= 10\nprint(s, end=\" \")","pseudo":"// \"/\" is integer division: 7 / 2 = 3\n\nInteger x = 1934\nInteger s = 0\nwhile (x > 0)\n  s = s + x mod 10\n  x = x / 10\nend while\nprint s"}'::jsonb),
