  ('coding', 'Loops', 2, 'What does this code print?', array['19', '13', '21', '12'], 3, 'continue skips the rest of the loop whenever i is a multiple of 3, so s adds every number from 1 to 6 except the multiples of 3: 12.', 50, 'coding-skip-multiples', '184e73bf88440cde', '{"c":"int s = 0;\nfor (int i = 1; i <= 6; i++) {\n  if (i % 3 == 0) continue;\n  s += i;\n}\nprintf(\"%d \", s);","cpp":"int s = 0;\nfor (int i = 1; i <= 6; i++) {\n  if (i % 3 == 0) continue;\n  s += i;\n}\ncout << s << \" \";","java":"int s = 0;\nfor (int i = 1; i <= 6; i++) {\n  if (i % 3 == 0) continue;\n  s += i;\n}\nSystem.out.print(s + \" \");","python":"s = 0\nfor i in range(1, 7):\n    if i % 3 == 0:\n        continue\n    s += i\nprint(s, end=\" \")","pseudo":"Integer s = 0\nfor i = 1 to 6\n  if (i mod 3 == 0)\n    continue\n  end if\n  s = s + i\nend for\nprint s"}'::jsonb),
